def calculate_premiums_C2() -> None:
    """Calculates premiums."""
    global WS_TOTAL_PREMIUMS, WS_EOF, INSURANCE_MASTER
    print("CALCULATING PREMIUMS...")
    WS_EOF = False
    for insurance_record in INSURANCE_MASTER:
        determine_base_premium_C2()
        apply_risk_factor_C2()
        final_premium = calculate_final_premium_C2()
        WS_TOTAL_PREMIUMS += final_premium
    WS_EOF = True

def determine_base_premium_C2() -> None:
    """Determines the base premium."""
    global WS_CALC_AMOUNT, INS_LIFE, INS_HEALTH, INS_AUTO, INS_HOME, INS_UMBRELLA, INS_COVERAGE_AMOUNT, WS_LIFE_RATE_PER_1000, WS_HEALTH_BASE_PREMIUM, WS_AUTO_BASE_PREMIUM, WS_HOME_RATE_PER_1000, WS_UMBRELLA_RATE
    if INS_LIFE:
        WS_CALC_AMOUNT = INS_COVERAGE_AMOUNT / 1000 * WS_LIFE_RATE_PER_1000
    elif INS_HEALTH:
        WS_CALC_AMOUNT = WS_HEALTH_BASE_PREMIUM
    elif INS_AUTO:
        WS_CALC_AMOUNT = WS_AUTO_BASE_PREMIUM
    elif INS_HOME:
        WS_CALC_AMOUNT = INS_COVERAGE_AMOUNT / 1000 * WS_HOME_RATE_PER_1000
    elif INS_UMBRELLA:
        WS_CALC_AMOUNT  = None  # TODO: was WS_UMBRELLA_RATE

def apply_risk_factor_C2() -> None:
    """Applies the risk factor."""
    global WS_CALC_AMOUNT, INS_CLAIMS_COUNT
    if INS_CLAIMS_COUNT > 2:
        WS_CALC_AMOUNT = WS_CALC_AMOUNT * Decimal("1.25")

def calculate_final_premium_C2() -> Decimal:
    """Calculates the final premium."""
    global WS_CALC_AMOUNT, INS_PREMIUM_AMOUNT
    INS_PREMIUM_AMOUNT  = None  # TODO: was WS_CALC_AMOUNT
    return WS_CALC_AMOUNT

