    while not working_storage_C4.ws_eof:
        # Simulating READ transaction_log NEXT with sample data
        # In a real application, you would replace this with actual data reading logic
        transaction_data = [
            (10000, False), (6000, False), (12000, False), (4000, False), (8000, False), (None, True)
        ]
        
        tran_amount, is_end_of_file = transaction_data.pop(0)
        
        if is_end_of_file:
            working_storage_C4.ws_eof = True
        else:
            working_storage_C4.tran_amount = Decimal(str(tran_amount)) if tran_amount is not None else None
