def set_interest_rate_C6(loan_type: str) -> None:
    """Sets the interest rate based on loan type."""
    global WS_INTEREST_RATE_C6
    if loan_type == "MTG":
        WS_INTEREST_RATE_C6 = Decimal("3.0")
    elif loan_type == "AUT":
        WS_INTEREST_RATE_C6 = Decimal("4.0")
    elif loan_type == "PER":
        WS_INTEREST_RATE_C6 = Decimal("5.0")
    else:
        WS_INTEREST_RATE_C6 = Decimal("2.0")

def calculate_simple_interest_C6() -> None:
    """Calculates simple interest."""
    global WS_SIMPLE_INTEREST_C6, WS_ACCOUNT_BALANCE_C6, WS_INTEREST_RATE_C6, WS_DAYS_IN_PERIOD_C6
    WS_SIMPLE_INTEREST_C6 = (
        WS_ACCOUNT_BALANCE_C6 * WS_INTEREST_RATE_C6 * WS_DAYS_IN_PERIOD_C6 / Decimal("36500.0")
    )

def calculate_compound_interest_C6() -> None:
    """Calculates compound interest."""
    global WS_COMPOUND_FACTOR_C6, WS_COMPOUND_INTEREST_C6, WS_ACCOUNT_BALANCE_C6, WS_INTEREST_RATE_C6, WS_DAYS_IN_PERIOD_C6
    WS_COMPOUND_FACTOR_C6 = (
        1 + WS_INTEREST_RATE_C6 / Decimal("36500.0")
    ) ** WS_DAYS_IN_PERIOD_C6
    WS_COMPOUND_INTEREST_C6 = (
        WS_ACCOUNT_BALANCE_C6 * (WS_COMPOUND_FACTOR_C6 - 1)
    )

def apply_interest_C6() -> None:
    """Applies interest to the account balance."""
    global WS_ACCOUNT_BALANCE_C6, WS_SIMPLE_INTEREST_C6, WS_COMPOUND_INTEREST_C6, WS_INTEREST_METHOD_C6
    if WS_INTEREST_METHOD_C6 == "S":
        WS_ACCOUNT_BALANCE_C6 += WS_SIMPLE_INTEREST_C6
    else:
        WS_ACCOUNT_BALANCE_C6 += WS_COMPOUND_INTEREST_C6
    update_account_C6()

def fee_processing_C6() -> None:
    """Processes fees."""
    calculate_monthly_fee_C6()
    calculate_transaction_fees_C6()
    apply_fee_waivers_C6()
    deduct_fees_C6()

def calculate_monthly_fee_C6() -> None:
    """Calculates the monthly fee based on account type."""
    global WS_MONTHLY_FEE_C6, WS_ACCOUNT_TYPE_C6
    if WS_ACCOUNT_TYPE_C6 == "CHK":
        WS_MONTHLY_FEE_C6 = Decimal("12.00")
    elif WS_ACCOUNT_TYPE_C6 == "SAV":
        WS_MONTHLY_FEE_C6 = Decimal("5.00")
    elif WS_ACCOUNT_TYPE_C6 == "PRM":
        WS_MONTHLY_FEE_C6 = Decimal("25.00")
    else:
        WS_MONTHLY_FEE_C6 = Decimal("0.00")

def calculate_transaction_fees_C6() -> None:
    """Calculates transaction fees based on transaction count."""
    global WS_TRANS_FEE_C6, WS_TRANS_COUNT_C6, WS_FREE_TRANS_LIMIT_C6, WS_EXCESS_TRANS_C6
    if WS_TRANS_COUNT_C6 > WS_FREE_TRANS_LIMIT_C6:
        WS_EXCESS_TRANS_C6 = WS_TRANS_COUNT_C6 - WS_FREE_TRANS_LIMIT_C6
        WS_TRANS_FEE_C6 = WS_EXCESS_TRANS_C6 * Decimal("0.0")
    else:
        WS_TRANS_FEE_C6 = Decimal("0.0")

def apply_fee_waivers_C6() -> None:
    """Applies fee waivers based on account balance and customer tier."""
    global WS_MONTHLY_FEE_C6, WS_TRANS_FEE_C6, WS_ACCOUNT_BALANCE_C6, WS_MIN_BALANCE_WAIVER_C6, WS_CUSTOMER_TIER_C6
    if WS_ACCOUNT_BALANCE_C6 >= WS_MIN_BALANCE_WAIVER_C6:
        WS_MONTHLY_FEE_C6 = Decimal("0.0")
    if WS_CUSTOMER_TIER_C6 == "GOLD" or WS_CUSTOMER_TIER_C6 == "PLATINUM":
        WS_TRANS_FEE_C6 = WS_TRANS_FEE_C6 * Decimal("0.5")

def deduct_fees_C6() -> None:
    """Deducts fees from the account balance."""
    global WS_TOTAL_FEES_C6, WS_ACCOUNT_BALANCE_C6, WS_MONTHLY_FEE_C6, WS_TRANS_FEE_C6
    WS_TOTAL_FEES_C6 = WS_MONTHLY_FEE_C6 + WS_TRANS_FEE_C6
    WS_ACCOUNT_BALANCE_C6 -= None  # TODO: was WS_TOTAL_FEES_C6
    update_account_C6()
    record_fee_transaction_C6()

