def generate_card_number_C10() -> None:
    """Generates card number."""
    ws_card_prefix: str = '4'
    ws_bin_number: Any = None
    ws_card_bin: Any = ws_bin_number
    ws_card_seq: int = int(0 * 999999999)
    ws_card_number_temp: str = f"{ws_card_prefix}{ws_card_bin}{ws_card_seq}"
    calculate_luhn_check_C10()
    ws_luhn_check: Any = None
    ws_card_number: str = f"{ws_card_number_temp}{ws_luhn_check}"


def calculate_luhn_check_C10() -> None:
    """Calculates Luhn check digit."""
    ws_luhn_sum: int = 0
    ws_card_number_temp: str = ''
    ws_luhn_check: int = 0

    for ws_luhn_idx in range(15, 0, -1):
        ws_luhn_digit: int = int(ws_card_number_temp[ws_luhn_idx - 1])
        if (16 - ws_luhn_idx) % 2 == 0:
            ws_luhn_digit *= 2
            if ws_luhn_digit > 9:
                ws_luhn_digit -= 9
        ws_luhn_sum += ws_luhn_digit
    
    ws_luhn_check = (10 - (ws_luhn_sum % 10)) % 10


def set_card_limits_C10() -> None:
    """Sets card limits."""
    ws_card_type: str = ''
    ws_daily_limit: int = 0
    ws_atm_limit: int = 0
    ws_credit_line: Any = None

    if ws_card_type == 'DEBIT':
        ws_daily_limit = 1000
        ws_atm_limit = 500
    elif ws_card_type == 'CREDIT':
        ws_daily_limit = ws_credit_line
        ws_atm_limit = int(ws_credit_line * 0.2)
    elif ws_card_type == 'PREMIUM':
        ws_daily_limit = 10000
        ws_atm_limit = 2000


